/**
 * What kind of document a [`SearchHit`] came from.
 *
 * Serialised as `"edition"`, `"work"`, or `"person"` (snake_case)
 * so the specta-generated TS type stays narrow.
 */

public enum HitKind: Equatable, Hashable {
    
    case edition
    case work
    case person





}

#if compiler(>=6)
extension HitKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHitKind: FfiConverterRustBuffer {
    typealias SwiftType = HitKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HitKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .edition
        
        case 2: return .work
        
        case 3: return .person
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HitKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .edition:
            writeInt(&buf, Int32(1))
        
        
        case .work:
            writeInt(&buf, Int32(2))
        
        
        case .person:
            writeInt(&buf, Int32(3))
        
        }
    }
}


